import {createServer as httpServer} from 'node:http';
import {readFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
export function createServer(){const tasks=[];return httpServer(async(req,res)=>{const json=(status,data)=>{res.writeHead(status,{'content-type':'application/json'});res.end(JSON.stringify(data));};try{if(req.url==='/api/tasks'&&req.method==='GET')return json(200,tasks);if(req.url==='/api/tasks'&&req.method==='POST'){let body='';for await(const chunk of req){body+=chunk;if(body.length>4096)return json(413,{error:'Too large'});}let data;try{data=JSON.parse(body);}catch{return json(400,{error:'Invalid JSON'});}if(typeof data.text!=='string'||!data.text.trim())return json(400,{error:'Task text is required'});const task={id:tasks.length+1,text:data.text.trim()};tasks.push(task);return json(201,task);}if(req.url==='/'&&req.method==='GET'){res.writeHead(200,{'content-type':'text/html; charset=utf-8'});return res.end(await readFile(new URL('./index.html',import.meta.url)));}json(404,{error:'Not found'});}catch{json(500,{error:'Unexpected failure'});}});}
if(process.argv[1]===fileURLToPath(import.meta.url)){const s=createServer();s.listen(Number(process.env.PORT??0),'127.0.0.1',()=>console.log('http://127.0.0.1:'+s.address().port));process.on('SIGTERM',()=>s.close());}

