import test from 'node:test';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {join} from 'node:path';
const root=process.env.AF_WORKSPACE;
const load=(name)=>import(pathToFileURL(join(root,name)));
test('API preserves arbitrary task text and state',async()=>{const {createServer}=await load('server.js');const s=createServer();await new Promise(r=>s.listen(0,'127.0.0.1',r));try{const base='http://127.0.0.1:'+s.address().port;const text='<img src=x onerror="document.body.dataset.exploited=1">';const r=await fetch(base+'/api/tasks',{method:'POST',body:JSON.stringify({text})});assert.equal(r.status,201);const rows=await fetch(base+'/api/tasks').then(r=>r.json());assert.deepEqual(rows.map(x=>x.text),[text]);assert.equal((await fetch(base+'/')).status,200);}finally{await new Promise(r=>s.close(r));}});
